select lives_ok($$select public.product_command('commercial.payment.record',jsonb_build_object('family_id','73000000-0000-4000-8000-000000000001','branch_id','72000000-0000-4000-8000-000000000001','amount_minor',15000,'method','bank_transfer','reference','COMMERCIAL-TEST-BALANCE','invoice_id',current_setting('test.commercial_invoice')),'75000000-0000-4000-8000-000000000006')$$,'Exact remainder pays invoice');
