select throws_ok($$select private.commercial_roster_event('76000000-0000-4000-8000-000000000007','reserve','Frozen booking')$$,'P0409',null,'Frozen membership cannot reserve');
select lives_ok($$select public.product_command('commercial.membership.freeze',jsonb_build_object('id',current_setting('test.commercial_member'),'frozen',false,'reason','Synthetic resume test'),'75000000-0000-4000-8000-000000000012')$$,'Resume rechecks eligibility');
select is((select count(*)::int from public.entitlement_ledger where membership_id=current_setting('test.commercial_member')::uuid and kind='grant'),1,'Resume never grants twice');
