select lives_ok($$select public.product_command('commercial.membership.renew',jsonb_build_object('id',current_setting('test.commercial_member'),'accepted',true),'75000000-0000-4000-8000-000000000014')$$,'Renewal creates next monthly period');
select lives_ok($$select public.product_command('commercial.membership.renew',jsonb_build_object('id',current_setting('test.commercial_member'),'accepted',true),'75000000-0000-4000-8000-000000000015')$$,'Different request key still deduplicates renewal');
select is((select count(*)::int from public.commercial_memberships where renewed_from=current_setting('test.commercial_member')::uuid),1,'Exactly one next period exists');
select is((select starts_on from public.commercial_memberships where renewed_from=current_setting('test.commercial_member')::uuid),(select expires_on from public.commercial_memberships where id=current_setting('test.commercial_member')::uuid),'Renewal is contiguous and nonoverlapping');
select lives_ok($$select public.product_command('commercial.payment.unallocate',jsonb_build_object('allocation_id',(select id from public.commercial_allocations where payment_id=current_setting('test.commercial_payment')::uuid and amount_minor>0),'reason','Synthetic refund correction'),'75000000-0000-4000-8000-000000000016')$$,'Allocation reverses as a separate entry');
select is((select status from public.commercial_memberships where id=current_setting('test.commercial_member')::uuid),'suspended','Uncovered membership suspends immediately');
select lives_ok($$select public.product_command('commercial.payment.refund',jsonb_build_object('payment_id',current_setting('test.commercial_payment'),'amount_minor',4000,'reason','Synthetic partial refund','reference','COMMERCIAL-REFUND-1'),'75000000-0000-4000-8000-000000000017')$$,'Unallocated funds permit a partial offline refund');
select is(private.commercial_unallocated(current_setting('test.commercial_payment')::uuid),6000::bigint,'Refund leaves exact unallocated remainder');
select lives_ok($$select public.product_command('commercial.credit.approve',jsonb_build_object('invoice_id',current_setting('test.commercial_invoice'),'expires_on',(now() at time zone 'Asia/Dubai')::date+7,'reason','Owner approved temporary credit'),'75000000-0000-4000-8000-000000000018')$$,'Credit approval independently activates membership');
