select is((select status from public.commercial_memberships where id=current_setting('test.commercial_member')::uuid),'active','Approved unexpired credit restores eligibility');
select lives_ok($$select public.product_command('commercial.credit.revoke',jsonb_build_object('id',(select id from public.commercial_credit_approvals where invoice_id=current_setting('test.commercial_invoice')::uuid),'reason','Owner revoked temporary credit'),'75000000-0000-4000-8000-000000000019')$$,'Credit can be revoked with preserved history');
select is((select status from public.commercial_memberships where id=current_setting('test.commercial_member')::uuid),'suspended','Credit revocation removes eligibility immediately');
insert into public.product_permissions(user_id,permission,branch_id,granted_by) values('71000000-0000-4000-8000-000000000004','finance.payment','72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001');
