select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select set_config('test.overbook_member',(public.product_command('commercial.membership.start',jsonb_build_object('package_id',current_setting('test.commercial_package'),'child_id','74000000-0000-4000-8000-000000000002','starts_on',(now() at time zone 'Asia/Dubai')::date,'accepted',true),'75000000-0000-4000-8000-000000000030')->>'id'),true);
select set_config('test.overbook_invoice',(select id::text from public.commercial_invoices where membership_id=current_setting('test.overbook_member')::uuid),true);
select throws_ok($$select public.product_command('commercial.payment.record',jsonb_build_object('family_id','73000000-0000-4000-8000-000000000001','branch_id','72000000-0000-4000-8000-000000000001','amount_minor',25010,'method','cash','reference','COMMERCIAL-OVERBOOK','invoice_id',current_setting('test.overbook_invoice')),'75000000-0000-4000-8000-000000000031')$$,'P0409',null,'Nine existing sessions cannot activate an eight-session package');
