select is((select status from public.commercial_memberships where id=current_setting('test.overbook_member')::uuid),'pending','Failed activation leaves original pending state');

-- A moved roster may reserve from a different period without colliding with its old ledger keys.
update public.class_sessions set starts_at=((select starts_on from public.commercial_memberships where renewed_from=current_setting('test.commercial_member')::uuid)+2)::timestamp at time zone 'Asia/Dubai',ends_at=(((select starts_on from public.commercial_memberships where renewed_from=current_setting('test.commercial_member')::uuid)+2)::timestamp at time zone 'Asia/Dubai')+interval '1 hour' where id='76000000-0000-4000-8000-000000000005';
select lives_ok($$select public.product_command('commercial.payment.record',jsonb_build_object('family_id','73000000-0000-4000-8000-000000000001','branch_id','72000000-0000-4000-8000-000000000001','amount_minor',25010,'method','bank_transfer','reference','COMMERCIAL-RENEWAL-PAYMENT','invoice_id',(select id from public.commercial_invoices where membership_id=(select id from public.commercial_memberships where renewed_from=current_setting('test.commercial_member')::uuid))),'75000000-0000-4000-8000-000000000033')$$,'Moved session can reserve entitlement in a new monthly period');
select is((select sum(available_delta)::int from public.entitlement_ledger where membership_id=(select id from public.commercial_memberships where renewed_from=current_setting('test.commercial_member')::uuid)),7,'New period reserves once without reusing old source key');
select lives_ok($$select public.product_command('commercial.package.status',jsonb_build_object('id',current_setting('test.commercial_package'),'active',false),'75000000-0000-4000-8000-000000000032')$$,'Package can stop new sales without losing history');
