select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.commercial_packages where id=current_setting('test.commercial_package')::uuid),1,'Family retains accepted terms after package stops new sales');
