select throws_ok($$update public.commercial_packages set price_minor=1 where id=current_setting('test.commercial_package')::uuid$$,'42501',null,'Accepted package prices are immutable even for maintenance');
select throws_ok($$update public.commercial_memberships set expires_on=expires_on+7 where id=current_setting('test.commercial_member')::uuid$$,'42501',null,'Contract periods cannot be silently rewritten');
select * from finish();
rollback;
